class ExuraEnvironment{static configure=new Map([["version","1.1.0"],["mode","production"],["url",`${window.location.protocol}//${window.location.host}/`]]);static module=new Map();static store=new Map();static render=new Map();static boiler=new Map();static state=new Map();static effect=new Map()}class ExuraDom{constructor(selector="body"){this.selector=selector;this.target=typeof selector==="string"?document.querySelector(selector):selector;return new Proxy(this,{get(target,prop){if(prop in target)return target[prop];if(typeof target.target[prop]==="function"){return(...args)=>{const result=target.target[prop](...args);return result===undefined?target:result}}return target.target[prop]},set(target,prop,value){target.target[prop]=value;return !0}})}text(content){if(content===undefined)return this.target.textContent;this.target.textContent=content;return this}html(content){if(content===undefined)return this.target.innerHTML;this.target.innerHTML=content;return this}attr(attr,value){if(value===undefined)return this.target.getAttribute(attr);this.target.setAttribute(attr,value);return this}append(content){this.target.append(content instanceof ExuraDom?content.target:content);return this}find(selector){const found=this.target.querySelector(selector);return found?new ExuraDom(found):null}on(event,callback){this.target.addEventListener(event,callback);return this}clear(){this.target.innerHTML=""}}class ExuraStore extends Map{constructor(entries){super(entries);}set(key,value){return super.set(key,value)}}class ExuraState extends Map{constructor(ID){super();this.ID=ID}set(key,value){const old=this.get(key);const changed=old!==value;super.set(key,value);if(changed){const effects=ExuraEnvironment.effect.get(this.ID)||[];for(const record of effects){if(record.deps===null){Exura.trigger(record);continue}if(!record.deps.includes(key))continue;const currVals=record.deps.map(dep=>this.get(dep));const depChanged=!currVals.every((v,i)=>v===record.lastValues[i]);if(depChanged){record.lastValues=currVals;Exura.trigger(record)}}}return this}}class Exura{static environment(env){}static module(fn){const ID=fn.name;fn.store=Exura.store(ID,{});fn.state=Exura.state(ID,{});if(document.querySelectorAll(`exura-${ID}`).length>0){const element=document.querySelector(`exura-${ID}`);ExuraEnvironment.render.set(ID,element);if(!ExuraEnvironment.boiler.has(ID)){ExuraEnvironment.boiler.set(ID,element.innerHTML)}fn.dom=Exura.dom(`exura-${ID}`);fn.render=(reBoiler)=>{Exura.render(ID,reBoiler)}}else{fn.dom=!1;fn.render=()=>{console.warn(`Component ${ID} Element Not Found`)}}fn.effect=(fn,dependencies)=>{Exura.effect(ID,fn,dependencies)};fn.watch=(target,fn2)=>{const found=fn.dom?fn.dom.find(target):null;if(!found){console.warn(`Component ${ID}: watch target ${target} not found`);return}Exura.watch(found.target,fn2)};fn.router=(url,fn,element)=>{Exura.router(url,fn,element)};ExuraEnvironment.module.set(ID,fn);window[ID]=ExuraEnvironment.module.get(ID)}static load(ID){if(ID){return[ExuraEnvironment.module.get(ID),ExuraEnvironment.store.get(ID),ExuraEnvironment.state.get(ID),ExuraEnvironment.effect.get(ID),ExuraEnvironment.render.get(ID)]}else{return ExuraEnvironment.module}}static store(ID,data){if(!ExuraEnvironment.store.has(ID)){ExuraEnvironment.store.set(ID,new ExuraStore())}if(data){const current=ExuraEnvironment.store.get(ID);ExuraEnvironment.store.set(ID,new ExuraStore([...current,...Object.entries(data)]))}return ExuraEnvironment.store.get(ID)||!1}static escape(value){return String(value).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll("\"","&quot;").replaceAll("'","&#39;")}static render(ID,reBoiler=null){if(reBoiler!==null){ExuraEnvironment.boiler.set(ID,reBoiler)}let boiler=ExuraEnvironment.boiler.get(ID);let render=ExuraEnvironment.render.get(ID);let store=ExuraEnvironment.store.get(ID);let state=ExuraEnvironment.state.get(ID);let data=new Map([...store,...state]);for(let[key,value] of data){boiler=boiler.replaceAll(`{{{${key}}}}`,value);boiler=boiler.replaceAll(`{{${key}}}`,Exura.escape(value))}render.innerHTML=boiler}static state(ID,newState={}){let store=ExuraEnvironment.state.get(ID);if(!store){store=new ExuraState(ID);ExuraEnvironment.state.set(ID,store)}for(const[key,val] of Object.entries(newState)){store.set(key,val)}return store}static effect(ID,effectFn,deps=null){const state=ExuraEnvironment.state.get(ID)||new ExuraState(ID);ExuraEnvironment.state.set(ID,state);const effects=ExuraEnvironment.effect.get(ID)||[];const record={deps,lastValues:deps?deps.map(dep=>state.get(dep)):[],effect:effectFn,running:!1};effects.push(record);ExuraEnvironment.effect.set(ID,effects);Exura.trigger(record)}static trigger(record){if(record.running||typeof record.effect!=="function")return;record.running=!0;try{record.effect()}finally{record.running=!1}}static router(endpoint,fn){const path=location.pathname;const keys=[];const pattern=endpoint.replace(/:([^/]+)/g,(_,key)=>{keys.push(key);return "([^/]+)"});const regex=new RegExp("^"+pattern+"$");const match=path.match(regex);if(match&&typeof fn==="function"){const params={};keys.forEach((k,i)=>{params[k]=match[i+1]});fn(params)}}static watch(element,fn,options={}){const{once=!0}=options;const observer=new IntersectionObserver((entries,observer)=>{entries.forEach(entry=>{if(entry.isIntersecting){fn(entry);if(once){observer.unobserve(entry.target)}}})});observer.observe(element)}static dom(selector){if(document.querySelector(`exura-${selector}`)){selector=`exura-${selector}`}return new ExuraDom(selector)}}